package com.cpf.education.online.transaction.required.service;
import com.cpf.data.persistence.api.CpfCrudRepository; import com.cpf.data.persistence.api.annotation.CpfTransactional; import com.cpf.education.online.transaction.required.dto.MemberRegistrationCommand; import com.cpf.education.online.transaction.required.repository.MemberRegistrationRecord; import com.cpf.foundation.annotation.CpfService; import org.springframework.beans.factory.ObjectProvider; import org.springframework.transaction.annotation.Propagation;
@CpfService
/** MemberRegistrationService는 여러 Service가 하나의 REQUIRED Local Transaction에 참여하는 Transaction Golden Path입니다. */
public class MemberRegistrationService { private final MemberProfileRegistrationService profiles; private final ObjectProvider<CpfCrudRepository<MemberRegistrationRecord,String>> repositories; public MemberRegistrationService(MemberProfileRegistrationService profiles,ObjectProvider<CpfCrudRepository<MemberRegistrationRecord,String>> repositories){this.profiles=profiles;this.repositories=repositories;}
 @CpfTransactional(propagation=Propagation.REQUIRED) public void register(MemberRegistrationCommand c){repository().save(new MemberRegistrationRecord(c.memberId(),"MEMBER","saved"));profiles.saveProfile(c);} private CpfCrudRepository<MemberRegistrationRecord,String> repository(){var r=repositories.getIfAvailable();if(r==null)throw new IllegalStateException("CPF transaction repository is not configured");return r;} }
